class Batch:
    def __init__(self): self.calls = 0
    @functools.cached_property
    def total(self):
        self.calls += 1
        return sum([2, 3, 5])
b = Batch()
(b.total, b.total, b.calls)

@functools.singledispatch
def describe(x): return 'object'
@describe.register(int)
def _(x): return 'integer'
[describe(3), describe('hi')]

class Describe:
    @functools.singledispatchmethod
    def kind(self, x): return 'object'
    @kind.register(int)
    def _(self, x): return 'integer'
d = Describe()
[d.kind(3), d.kind('hi')]

@functools.total_ordering
class Score:
    def __init__(self, n): self.n = n
    def __eq__(self, other): return self.n == other.n
    def __lt__(self, other): return self.n < other.n
(Score(2) <= Score(2), Score(3) > Score(2), Score(1) >= Score(2))

def double(x): return 2 * x
@functools.wraps(double)
def wrapper(x): return double(x)
(wrapper.__name__, wrapper(4), wrapper.__wrapped__ is double)

@functools.lru_cache(maxsize=None)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)
fib(80)

@functools.cache
def f(n):
    return n * n
[f(3), f(3), f.cache_info().hits]
